import sys
import bisect

def compute_comb(n):
    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        comb[i][0] = 1
        for j in range(1, i + 1):
            comb[i][j] = comb[i-1][j-1] + comb[i-1][j]
    return comb

def get_difs(conf, a_bef, b_bef, r, c, comb):
    ans = 0
    for i in range(c + 1):
        if conf & (1 << i):
            b_bef += 1
            aux1 = comb[b_bef - 1][r - 1]
            aux2 = comb[n - b_bef][r] - comb[a_bef][r]
            ans -= aux1 * aux2
        else:
            a_bef += 1
            aux1 = comb[a_bef - 1][r - 1]
            aux2 = comb[n - a_bef][r] - comb[b_bef][r]
            ans += aux1 * aux2
    return ans

def check(conf, s, r, c):
    for i in range(c + 1):
        idx = 2 * r + c + i - 1  # original s[2*r+c+i] -> Python index
        if s[idx] == 'A' and ((conf >> i) & 1):
            return False
        if s[idx] == 'B' and not ((conf >> i) & 1):
            return False
    return True

def compute_second_part(r, c, s, comb, partial, partial_zero):
    limit = 1 << (c + 1)
    for conf in range(limit):
        b_here = bin(conf).count('1')
        a_here = c + 1 - b_here
        val = get_difs(conf, r + c - a_here, r + c - b_here, r, c, comb)
        if check(conf, s, r, c):
            partial[a_here].append(val)
        else:
            partial_zero[a_here].append(val)
    for i in range(c + 2):
        partial[i].sort()
        partial_zero[i].sort()

def get_coef(conf, s, r, c, comb, cnt_a, cnt_b):
    i = 0
    while i < c + 1:
        if ((conf >> i) & 1) != (conf & 1):
            break
        i += 1
    for j in range(i, c + 1):
        idx = 2 * r - 1 + j - 1  # original s[2*r-1+j] -> Python index
        if s[idx] == 'A' and ((conf >> j) & 1):
            return 0
        if s[idx] == 'B' and not ((conf >> j) & 1):
            return 0
    set_a = r - 1 + (0 if (conf & 1) == 0 else i)
    set_b = r - 1 + (i if (conf & 1) == 1 else 0)
    idx_cnt = 2 * r - 2 + i  # original index for cnt_a/cnt_b
    if set_a < cnt_a[idx_cnt]:
        return 0
    if set_b < cnt_b[idx_cnt]:
        return 0
    return comb[set_a + set_b - cnt_a[idx_cnt] - cnt_b[idx_cnt]][set_a - cnt_a[idx_cnt]]

def upd(ans, act):
    # ans is (min_abs, count), act is (value, count)
    val, cnt = act
    if val < 0:
        val = -val
    if ans[0] < val:
        return ans
    if ans[0] > val:
        return (val, cnt)
    return (ans[0], ans[1] + cnt)

def how_many(data, val):
    left = bisect.bisect_left(data, val)
    right = bisect.bisect_right(data, val)
    return right - left

def compute_first_part(r, c, s, comb, cnt_a, cnt_b, partial, partial_zero):
    limit = 1 << (c + 1)
    ans = (1 << 60, 0)
    for conf in range(limit):
        b_here = bin(conf).count('1')
        a_here = c + 1 - b_here
        act = get_difs(conf, r - 1, r - 1, r, c, comb)
        coef = get_coef(conf, s, r, c, comb, cnt_a, cnt_b)
        # search in partial[c+1-a_here]
        lst = partial[c + 1 - a_here]
        it = bisect.bisect_left(lst, -act)
        if it < len(lst):
            val = lst[it] + act
            if ans[0] >= abs(val):
                cnt = how_many(lst, lst[it])
                ans = upd(ans, (val, coef * cnt))
        if it > 0:
            it -= 1
            val = lst[it] + act
            if ans[0] >= abs(val):
                cnt = how_many(lst, lst[it])
                ans = upd(ans, (val, coef * cnt))
        # search in partial_zero[c+1-a_here]
        lst0 = partial_zero[c + 1 - a_here]
        it = bisect.bisect_left(lst0, -act)
        if it < len(lst0):
            val = lst0[it] + act
            if ans[0] >= abs(val):
                cnt = how_many(lst0, lst0[it])
                ans = upd(ans, (val, coef * cnt))
        if it > 0:
            it -= 1
            val = lst0[it] + act
            if ans[0] >= abs(val):
                cnt = how_many(lst0, lst0[it])
                ans = upd(ans, (val, coef * cnt))
    return ans[1]

def main():
    global n
    data = sys.stdin.read().split()
    if not data:
        return
    r = int(data[0])
    c = int(data[1])
    s_str = data[2].strip()
    n = 2 * (r + c)
    # ensure s_str length is n, but we trust input
    s = list(s_str)  # 0-indexed, s[0] corresponds to original s[1]
    comb = compute_comb(n)
    cnt_a = [0] * (n + 1)
    cnt_b = [0] * (n + 1)
    for i in range(1, n + 1):
        cnt_a[i] = cnt_a[i-1] + (1 if s[i-1] == 'A' else 0)
        cnt_b[i] = cnt_b[i-1] + (1 if s[i-1] == 'B' else 0)
    partial = [[] for _ in range(c + 2)]
    partial_zero = [[] for _ in range(c + 2)]
    compute_second_part(r, c, s, comb, partial, partial_zero)
    sol = compute_first_part(r, c, s, comb, cnt_a, cnt_b, partial, partial_zero)
    print(sol)

if __name__ == "__main__":
    main()
